LEVEL = 1
CFG = {1: [("allow", "read"), ("allow", "write")], 2: [("allow", "read"), ("deny", "read")], 3: [("deny", "delete"), ("allow", "delete"), ("allow", "read")]}
rules = CFG[LEVEL]
seen, conflicts = {}, []
for effect, op in rules:
    if op in seen and seen[op] != effect:
        conflicts.append(op)
    seen[op] = effect
print("rules:", rules, "| contradictions:", conflicts or ["none"])

